const TABS = ['2026Instock','Animal','Balustrade','Bathtub','Bench','BookMatchedSlabs','Carving','Columns','DoorSurround','Exterior-Wall-Decoration','Fireplace','Fountain','Lamppost','Marble+ Basin','Marble+ ConsoleTable','MarbleMedallion','MarbleRangeHood','MarbleSlab','Moulding','OutdoorCornice','Planter','Sink','Stairs','Statue','StoneMosaicTile','Table','Vanity','Wainscoting','Wall-Coverings','WindowSurround'];
const meta = $('Sheet Meta').first().json.sheets || [];
const byTitle = {};
meta.forEach(s => { byTitle[s.properties.title] = s.properties; });
return TABS.filter(t => byTitle[t]).map(t => ({ json: { sheet_name: t, sheetId: byTitle[t].sheetId, columnCount: (byTitle[t].gridProperties || {}).columnCount || 26 } }));

const DOC = $('Config').first().json.docId;
const tabs = $('Tabs').all().map(i => i.json);
const norm = s => String(s == null ? '' : s).toLowerCase().replace(/\s+/g, ' ').trim();
const ETSY = ['Etsy_listing_id', 'Etsy_url', 'Etsy_admin_url', 'Etsy_status', 'Etsy_error', 'Etsy_created_at', 'Etsy_last_modified', 'Etsy_price_cad', 'Etsy_category_id', 'Etsy_image_count', 'Etsy_synced_at', 'Etsy_fields_to_update', 'Etsy_ready_to_post'];
const READ = ['Etsy_listing_id', 'Etsy_url', 'Etsy_admin_url', 'Etsy_status', 'Etsy_created_at', 'Etsy_last_modified', 'Etsy_price_cad', 'Etsy_category_id', 'Etsy_image_count', 'Etsy_synced_at'];
const letters = (n) => { let s = ''; n += 1; while (n > 0) { const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); } return s; };
const q = (s) => `'${String(s).replace(/'/g, "''")}'`;
return $input.all().map((it, i) => {
  const t = tabs[i];
  const headers = (it.json.values && it.json.values[0]) || [];
  const hn = headers.map(norm);
  const skuIdx = Math.max(hn.lastIndexOf('product no.'), hn.lastIndexOf('product no'));
  let lastNonEmpty = -1;
  hn.forEach((h, k) => { if (h) lastNonEmpty = k; });
  const titleIdx = hn.indexOf('title_etsy');
  const noHeader = lastNonEmpty < 0, noSku = skuIdx < 0;
  const cols = {}, newCols = [];
  let next = lastNonEmpty + 1;
  for (const name of ETSY) {
    const k = hn.lastIndexOf(norm(name));
    if (k >= 0) cols[name] = k; else if (!noHeader && !noSku) { cols[name] = next++; newCols.push(name); }
  }
  const maxIdx = Math.max(lastNonEmpty, ...Object.values(cols));
  const expandBy = (noHeader || noSku) ? 0 : Math.max(0, maxIdx + 1 - t.columnCount);
  const readKeys = [], ranges = [];
  if (!noHeader && !noSku) {
    readKeys.push('sku'); ranges.push(`${q(t.sheet_name)}!${letters(skuIdx)}3:${letters(skuIdx)}`);
    for (const name of READ) if (!newCols.includes(name)) { readKeys.push(name); ranges.push(`${q(t.sheet_name)}!${letters(cols[name])}3:${letters(cols[name])}`); }
  } else ranges.push(`${q(t.sheet_name)}!A2:A2`);
  const url = `https://sheets.googleapis.com/v4/spreadsheets/${DOC}/values:batchGet?majorDimension=COLUMNS&valueRenderOption=FORMATTED_VALUE&` + ranges.map(r => 'ranges=' + encodeURIComponent(r)).join('&');
  return { json: { tab: t.sheet_name, sheetId: t.sheetId, expandBy, skuIdx, titleIdx, cols, newCols, readKeys, url, noHeader, noSku, letters: Object.fromEntries(Object.entries(cols).map(([k, v]) => [k, letters(v)])) } };
});

const plans = $('Plan Columns').all().map(i => i.json);
const out = [];
$input.all().forEach((it, i) => {
  const p = plans[i];
  const vr = it.json.valueRanges || [];
  const cols = {};
  p.readKeys.forEach((k, j) => { cols[k] = (vr[j] && vr[j].values && vr[j].values[0]) || []; });
  const rows = [];
  if (p.readKeys.length) {
    const n = (cols.sku || []).length;
    for (let r = 0; r < n; r++) {
      const sku = String(cols.sku[r] == null ? '' : cols.sku[r]).trim().toUpperCase();
      if (!sku) continue;
      const g = k => String((cols[k] || [])[r] == null ? '' : cols[k][r]).trim();
      const cur = {}; p.readKeys.forEach(k => { if (k !== 'sku') cur[k] = g(k); }); rows.push({ row: r + 3, sku, cur });
    }
  }
  out.push({ tab: p.tab, rows });
});
return [{ json: { tabs: out } }];

const pages = [];
for (let o = 0; o <= 900; o += 100) pages.push({ state: 'active', offset: o });
for (const s of ['draft', 'inactive']) pages.push({ state: s, offset: 0 });
return pages.map(p => ({ json: p }));

const cfg = $('Config').first().json;
const dryRun = cfg.dryRun !== false;
const plans = $('Plan Columns').all().map(i => i.json);
const state = $('Sheet State').first().json.tabs;
const pages = $('Plan Pages').all().map(i => i.json);
const listings = [], etsyErrors = [];
$('List Page').all().forEach((it, i) => {
  const r = it.json;
  if (r.error || !Array.isArray(r.results)) { etsyErrors.push({ page: pages[i], error: r.error || r.message || 'no results' }); return; }
  for (const l of r.results) listings.push({ id: String(l.listing_id), state: l.state, sku: String((l.skus || [])[0] || '').trim().toUpperCase(), url: l.url || '', created: l.created_timestamp, modified: l.last_modified_timestamp, price: l.price ? String(l.price.amount / l.price.divisor) : '', category: l.taxonomy_id, images: (l.images || []).length });
});
const iso = ts => ts ? new Date(ts * 1000).toISOString().slice(0, 19) + 'Z' : '';
const nowIso = new Date().toISOString().slice(0, 19) + 'Z';
const STATIC = ['Etsy_listing_id', 'Etsy_url', 'Etsy_created_at', 'Etsy_category_id'];
const bySku = {};
listings.forEach(l => { if (l.sku) (bySku[l.sku] = bySku[l.sku] || []).push(l); });
const sheetSkus = new Set();
const tabsOut = [], notes = [], conflicts = [], formatRequests = [], formatSkipped = [];
const tot = { rowsMatched: 0, newCells: 0, alreadyCorrect: 0, conflicts: 0, live: 0, duplicate: 0, draft: 0, inactive: 0 };
plans.forEach((p, i) => {
  const st = state[i];
  if (p.noHeader || p.noSku) { notes.push({ tab: p.tab, skipped: p.noHeader ? 'no header row' : 'no Product No. column' }); return; }
  const writes = {};
  const put = (col, row, val) => { (writes[col] = writes[col] || []).push({ row, val }); };
  let matched = 0;
  st.rows.forEach(r => {
    sheetSkus.add(r.sku);
    const m = bySku[r.sku];
    if (!m) return;
    matched++;
    const act = m.filter(l => l.state === 'active');
    let status, pick, err = '';
    if (act.length > 1) { status = 'duplicate_on_etsy'; pick = act[0]; err = 'also: ' + act.slice(1).map(l => l.id).join(', '); tot.duplicate++; }
    else if (act.length === 1) { status = 'live'; pick = act[0]; tot.live++; }
    else { pick = m[0]; status = pick.state; tot[status] = (tot[status] || 0) + 1; }
    const want = { Etsy_listing_id: pick.id, Etsy_url: pick.url, Etsy_admin_url: `https://www.etsy.com/your/shops/me/listing-editor/edit/${pick.id}`, Etsy_status: status, Etsy_created_at: iso(pick.created), Etsy_last_modified: iso(pick.modified), Etsy_price_cad: pick.price, Etsy_category_id: String(pick.category || ''), Etsy_image_count: String(pick.images), Etsy_synced_at: nowIso };
    for (const [col, val] of Object.entries(want)) {
      const cur = r.cur[col] === undefined ? '' : r.cur[col];
      if (cur === '') { put(col, r.row, val); tot.newCells++; }
      else if (cur === val) tot.alreadyCorrect++;
      else if (!STATIC.includes(col)) { put(col, r.row, val); tot.refreshed = (tot.refreshed || 0) + 1; }
      else { tot.conflicts++; conflicts.push({ tab: p.tab, row: r.row, sku: r.sku, col, sheet: cur, etsy: val }); }
    }
    if (err) put('Etsy_error', r.row, err);
  });
  tot.rowsMatched += matched;
  const data = [];
  p.newCols.forEach(name => data.push({ range: `'${p.tab.replace(/'/g, "''")}'!${p.letters[name]}2`, values: [[name]] }));
  for (const [col, list] of Object.entries(writes)) {
    list.sort((a, b) => a.row - b.row);
    let run = null;
    const flush = () => { if (run) data.push({ range: `'${p.tab.replace(/'/g, "''")}'!${p.letters[col]}${run.start}:${p.letters[col]}${run.end}`, values: run.vals }); };
    for (const w of list) {
      if (run && w.row === run.end + 1) { run.end = w.row; run.vals.push([w.val]); }
      else { flush(); run = { start: w.row, end: w.row, vals: [[w.val]] }; }
    }
    flush();
  }
  // Header look: every Etsy column copies the format of the sheet's own "Title_Etsy" header (green), so the block reads as "belongs to Etsy"
  if (p.titleIdx < 0) formatSkipped.push(p.tab);
  else {
    const cell = c => ({ sheetId: p.sheetId, startRowIndex: 1, endRowIndex: 2, startColumnIndex: c, endColumnIndex: c + 1 });
    Object.values(p.cols).forEach(c => formatRequests.push({ copyPaste: { source: cell(p.titleIdx), destination: cell(c), pasteType: 'PASTE_FORMAT', pasteOrientation: 'NORMAL' } }));
  }
  tabsOut.push({ tab: p.tab, sheetId: p.sheetId, expandBy: p.expandBy, newHeaders: p.newCols, rows: st.rows.length, matched, writeRanges: data.length, data });
});
const etsyNotInSheet = listings.filter(l => !sheetSkus.has(l.sku)).map(l => ({ id: l.id, state: l.state, sku: l.sku }));
return [{ json: { dryRun, etsyListingsRead: listings.length, etsyErrors, totals: tot, notes, etsyNotInSheet,
  conflictSample: conflicts.slice(0, 20),
  headerColorRequests: formatRequests.length, tabsWithoutTitleEtsyHeader: formatSkipped, formatRequests,
  perTab: tabsOut.map(t => ({ tab: t.tab, rows: t.rows, matched: t.matched, newHeaders: t.newHeaders, addColumns: t.expandBy, writeRanges: t.writeRanges })),
  tabs: tabsOut } }];

const p = $('Compute Plan').first().json;
const { tabs, formatRequests, ...rest } = p;
return [{ json: { ...rest, message: p.dryRun ? 'DRY RUN: nothing was written. Set dryRun to false in Config to write.' : 'Writing... see Final Report.' } }];

const p = $('Compute Plan').first().json;
if (p.dryRun) return [];
return p.tabs.filter(t => t.data.length > 0).map(t => ({ json: { tab: t.tab, sheetId: t.sheetId, expandBy: t.expandBy, expandBody: { requests: [{ appendDimension: { sheetId: t.sheetId, dimension: 'COLUMNS', length: t.expandBy } }] }, valuesBody: { valueInputOption: 'RAW', data: t.data } } }));

const res = $('Write Values').all();
const errs = res.filter(r => r.json.error || r.json.message).map(r => r.json.error || r.json.message);
const fmt = $('Format Headers').first().json;
const p = $('Compute Plan').first().json;
return [{ json: { tabsWritten: res.length, cellsUpdated: res.reduce((a, r) => a + (r.json.totalUpdatedCells || 0), 0), errors: errs, headerColor: { requestsSent: p.headerColorRequests, repliesReceived: (fmt.replies || []).length, tabsWithoutTitleEtsyHeader: p.tabsWithoutTitleEtsyHeader, error: fmt.error || null }, totals: p.totals } }];
